            {visualMode === 'compare' && <ComparisonPanel key={`${interval.start}:${interval.end}`} data={data} interval={interval} cases={cases} services={services} onEvidence={e => { evidence(e); replay.seek(e.interval.end); }}/> }
            {(visualMode === 'robot' || visualMode === 'markers') && <RecordingContext prediction={visiblePrediction} display={visualMode === 'robot' ? 'robot' : 'overview'} datasetId={datasetId} data={data} playhead={replay.playhead} interval={effectiveInterval} highlighted={highlighted} onMarker={marker} onHighlight={id => setHighlighted(h => h.includes(id) ? h.filter(x => x !== id) : [id])} onData={() => { replay.pause(); setView('data'); }}/>}
            {(visualMode === 'robot' || visualMode === 'signals') && <SignalViewer visibleChannelIds={visualMode === 'robot' ? previewChannels : undefined} data={data} playhead={replay.playhead} interval={effectiveInterval} viewport={validViewport} highlighted={highlighted} following={following} zoom={zoom} onSelect={select} onFollow={() => { setFollowing(true); setZoom(10); }} onZoom={n => { setFollowing(true); setZoom(n); }}/>}
          </div>
        </div>
        {view === 'data' && <div className="secondary-view"><button className="text-button back-inspect" onClick={() => setView('inspect')}><ArrowLeft size={14}/>Back to replay</button><DataWorkspace services={services} data={data} onOpenRecording={onOpenRecording}/></div>}
        {view === 'evaluation' && <div className="secondary-view"><button className="text-button back-inspect" onClick={() => setView('inspect')}><ArrowLeft size={14}/>Back to replay</button><EvaluationWorkspace /></div>}
      </main>
    </div>
    {view === 'inspect' && <><footer className="transport"><div className="transport-controls"><button className="icon-button" aria-label="Replay from beginning" title="Replay from beginning" onClick={() => { setReplayStop(undefined); setFollowing(true); setHighlighted([]); replay.restart(); }}><RotateCcw size={15}/></button><button className="icon-button" aria-label="Previous publisher marker" disabled={!data.events.some(e => e.timeSeconds < effectiveInterval.start)} onClick={() => navigateMarker(-1)}><SkipBack size={15}/></button><button className="play-button" aria-label={replay.playing ? 'Pause replay' : 'Play replay'} onClick={() => { if (!replay.playing) setFollowing(true); replay.toggle(); }}>{replay.playing ? <Pause size={17} fill="currentColor"/> : <Play size={17} fill="currentColor"/>}</button><button className="icon-button" aria-label="Next publisher marker" disabled={!data.events.some(e => e.timeSeconds > Math.max(interval.end, replay.playhead))} onClick={() => navigateMarker(1)}><SkipForward size={15}/></button></div><div className="replay-clock"><strong className="mono">{timecode(replay.playhead, true)}</strong><span className="mono">/ {timecode(data.recording.durationSeconds)}</span></div><div className="timeline-control"><label className="sr-only" htmlFor="playhead">Replay position in seconds</label><input id="playhead" type="range" min="0" max={data.recording.durationSeconds} step="0.001" value={replay.playhead} onChange={e => seek(Number(e.target.value))} style={{ '--progress': `${replay.playhead/data.recording.durationSeconds*100}%` } as React.CSSProperties}/><div className="timeline-marks">{data.events.map(e => <button key={e.id} className={e.timeSeconds <= replay.playhead ? 'reached' : 'upcoming'} style={{ left: `${e.timeSeconds/data.recording.durationSeconds*100}%` }} aria-label={`${e.label}, publisher annotation at ${e.timeSeconds.toFixed(3)} seconds${e.timeSeconds > replay.playhead ? ', upcoming' : ''}`} title={`${e.label} · ${e.timeSeconds.toFixed(3)} s · publisher annotation`} onClick={() => marker(e)}/>)}</div></div><label className="speed-control"><span className="sr-only">Playback speed</span><select aria-label="Playback speed" value={replay.speed} onChange={e => replay.setSpeed(Number(e.target.value))}>{[.5,1,2,4].map(n => <option key={n} value={n}>{n}×</option>)}</select></label><span className="play-state">{replay.playing ? 'Playing' : 'Paused'}</span></footer>
    <div className="selection-footer"><span><span className="selection-dot"/>Investigation interval <strong className="mono">{intervalLabel(effectiveInterval)}</strong></span><form onSubmit={e => { e.preventDefault(); select({ start: Number(draftStart), end: Number(draftEnd) }); }}><label>From <input aria-label="Selection start seconds" type="number" step="0.001" min="0" max={data.recording.durationSeconds} value={draftStart} onChange={e => setDraftStart(e.target.value)}/></label><label>to <input aria-label="Selection end seconds" type="number" step="0.001" min="0" max={data.recording.durationSeconds} value={draftEnd} onChange={e => setDraftEnd(e.target.value)}/></label><button type="submit">Apply</button></form><button className="text-button" disabled={replay.playhead < 1.024} onClick={() => { const end = Math.floor(replay.playhead * 1000) / 1000; select({ start: Math.round((end - 1.024) * 1000) / 1000, end }); }}>Select at cursor</button>{selectionError && <span role="alert" className="error-message">{selectionError}</span>}</div></>}
  </div>;
}
