    `- **Input receipt:** ${markdownText(receipt?.samplesPerChannel ?? 'not provided')} samples/channel; SHA-256 ${markdownText(receipt?.inputSha256 ?? 'not provided')}`,
    '',
    evidence,
    '',
    '## Limitations',
    '',
    ...report.limitations.map(item => `- ${markdownText(item)}`),
    '',
  ].join('\n');
}

