      `- ${fixed(annotation.timeSeconds)} s — ${markdownText(annotation.label)} (${markdownText(annotation.source)})`).join('\n')
    : '- No publisher annotation falls inside this interval.';
  const measurements = report.measurements.channels.map(channel =>
    `| ${markdownText(channel.name)} | ${fixed(channel.range)} ${markdownText(channel.unit)} | ${fixed(channel.signedPeak)} ${markdownText(channel.unit)} | ${fixed(channel.peakTimeSec)} s |`).join('\n');
  const evidence = report.interpretation.evidence.length
    ? report.interpretation.evidence.map(item =>
      `- ${markdownText(item.label)} — ${fixed(item.interval.start)}–${fixed(item.interval.end)} s; ${item.channelIds?.map(markdownText).join(', ') ?? markdownText(item.channelId)}`).join('\n')
    : '- No separate evidence links were returned.';
  const receipt = report.interpretation.inputReceipt && typeof report.interpretation.inputReceipt === 'object'
    ? report.interpretation.inputReceipt as { samplesPerChannel?: unknown; inputSha256?: unknown }
    : undefined;
  const answer = report.interpretation.answer.split(/\n\s*\n/).map(markdownText).filter(Boolean).join('\n\n');
  const reviewNotes = report.reviewNotes.length ? report.reviewNotes.map(item => `- ${markdownText(item)}`) : ['- No model/measurement disagreement was flagged by the current review checks.'];
  return [
    '# Trace incident investigation',
    '',
    '> Retrospective robot telemetry report. Measurements, publisher annotations, and generated predictions are recorded as separate evidence sources.',
    '',
    '## Incident',
    '',
    `- **Recording:** ${markdownText(report.recording.recordingId)}`,
    `- **Source dataset:** ${markdownLink(report.recording.sourceUrl)}`,
    `- **Selected window:** [${fixed(report.window.startSec)}, ${fixed(report.window.endSec)}) s`,
    `- **Question:** ${markdownText(report.question)}`,
    '',
    '## Interpretation',
    '',
    `**Origin:** ${markdownText(report.interpretation.origin)} · **Source:** ${markdownText(report.interpretation.source)}`,
    '',
    answer || 'No interpretation was returned.',
    '',
    '## Review before handoff',
    '',
    ...reviewNotes,
    '',
    '## Measured torque',
    '',
    `${markdownText(report.measurements.method)}.`,
    '',
    '| Joint | Range | Signed absolute peak | Peak time |',
    '| --- | ---: | ---: | ---: |',
    measurements,
    '',
    '## Publisher annotations',
    '',
    annotations,
    '',
    '## Evidence and provenance',
    '',
    `- **Input:** ${report.window.samplesPerChannel} samples per channel at ${report.window.sampleRateHz} Hz (${markdownText(report.window.resolution)})`,
    `- **Model:** ${markdownText(report.interpretation.modelId ?? 'not applicable')}`,
    `- **Revision:** ${markdownText(report.interpretation.modelRevision ?? 'not provided')}`,
    `- **Input receipt:** ${markdownText(receipt?.samplesPerChannel ?? 'not provided')} samples/channel; SHA-256 ${markdownText(receipt?.inputSha256 ?? 'not provided')}`,
    '',
    evidence,
    '',
    '## Limitations',
    '',
    ...report.limitations.map(item => `- ${markdownText(item)}`),
    '',
  ].join('\n');
}

function download(content: string, type: string, filename: string): void {
  const url = URL.createObjectURL(new Blob([content], { type }));
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link); link.click(); link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function reportFilename(data: DemoData, answer: InvestigationAnswer, extension: string): string {
  return `trace-${data.recording.id.replace(/[^a-zA-Z0-9_-]/g, '_')}-${answer.interval.start.toFixed(3)}s.${extension}`;
}

export function downloadInvestigationMarkdown(data: DemoData, datasetId: string, answer: InvestigationAnswer) {
  const report = buildInvestigationReport(data, datasetId, answer);
  download(renderInvestigationMarkdown(report), 'text/markdown;charset=utf-8', reportFilename(data, answer, 'md'));
}

export function downloadInvestigationJson(data: DemoData, datasetId: string, answer: InvestigationAnswer) {
  const report = buildInvestigationReport(data, datasetId, answer);
  download(JSON.stringify(report, null, 2) + '\n', 'application/json', reportFilename(data, answer, 'json'));
}
export type StructuredPrediction = {
  contact: boolean;
  event_type: 'free' | 'intentional' | 'accidental';
  onset_ms: number | null;
  strongest_joint: string | null;
  affected_joints: string[];
  evidence_start_ms: number | null;
  evidence_end_ms: number | null;
};

function timing(value: unknown): number | null | undefined {
  if (value === null) return null;
  return typeof value === 'number' && Number.isFinite(value) && value >= 0 && value < 1024 ? value : undefined;
}

/** Keep only the supported prediction payload; generated prose is not telemetry evidence. */
export function structuredPrediction(output?: string): StructuredPrediction | undefined {
  if (!output) return;
  try {
    const first = output.indexOf('{'), last = output.lastIndexOf('}');
    const p = JSON.parse(output.slice(first, last + 1));
    if (!p || typeof p !== 'object' || !['free', 'intentional', 'accidental'].includes(p.event_type)) return;
    if (p.contact !== (p.event_type !== 'free')) return;
    const joint = p.strongest_joint === null ? null : typeof p.strongest_joint === 'string' && /^J[1-7]$/.test(p.strongest_joint) ? p.strongest_joint : undefined;
    const affected = Array.isArray(p.affected_joints) && p.affected_joints.every((value: unknown) => typeof value === 'string' && /^J[1-7]$/.test(value))
      ? [...new Set(p.affected_joints as string[])] : undefined;
    const onset = timing(p.onset_ms), evidenceStart = timing(p.evidence_start_ms), evidenceEnd = timing(p.evidence_end_ms);
    if (joint === undefined || affected === undefined || onset === undefined || evidenceStart === undefined || evidenceEnd === undefined) return;
    if (p.event_type === 'free' && (joint !== null || affected.length || onset !== null || evidenceStart !== null || evidenceEnd !== null)) return;
    if (p.event_type !== 'free' && (joint === null || onset === null)) return;
    if ((evidenceStart === null) !== (evidenceEnd === null) || (evidenceStart !== null && evidenceEnd !== null && evidenceEnd < evidenceStart)) return;
    return { contact: p.contact, event_type: p.event_type, onset_ms: onset, strongest_joint: joint,
      affected_joints: affected, evidence_start_ms: evidenceStart, evidence_end_ms: evidenceEnd };
  } catch { return; }
}

/** A compact operator view of the supported generated fields. */
export function predictionBrief(output?: string) {
  const p = structuredPrediction(output);
  if (!p) return;
  return {
    title: p.event_type === 'free' ? 'Free motion predicted' : p.event_type === 'intentional' ? 'Intentional contact predicted' : 'Accidental contact predicted',
    strongest: p.strongest_joint ?? undefined,
    onset: p.onset_ms ?? undefined,
  };
}

/** Convert relative generated onset to recording time, without inventing contact location. */
export function predictionCue(output: string | undefined, interval: { start: number; end: number }) {
  const brief = predictionBrief(output);
  if (!brief || brief.title === 'Free motion predicted' || brief.onset === undefined ||
    !Number.isFinite(interval.start) || !Number.isFinite(interval.end) || interval.start < 0 || Math.abs(interval.end - interval.start - 1.024) > 1e-8) return;
  return { title: brief.title, onsetSeconds: interval.start + brief.onset / 1000,
    channelId: brief.strongest ? `joint_${brief.strongest.slice(1)}` : undefined, interval: { ...interval } };
}
export type PredictionCue = NonNullable<ReturnType<typeof predictionCue>>;

